def maximumLength(nums, k):
    n = len(nums)
    # dp[i][c] = length of the longest good subsequence ending at i using at most c changes
    dp = [[1] * (k + 1) for _ in range(n)]
    maxlen = 1

    for i in range(n):
        for j in range(i):
            for c in range(k + 1):
                if nums[i] == nums[j]:
                    # No change needed to extend the subsequence
                    if dp[j][c] + 1 > dp[i][c]:
                        dp[i][c] = dp[j][c] + 1
                elif c > 0:
                    # Need one change to attach nums[i] after nums[j]
                    if dp[j][c - 1] + 1 > dp[i][c]:
                        dp[i][c] = dp[j][c - 1] + 1
        # Update answer
        maxlen = max(maxlen, max(dp[i]))

    return maxlen
